{
  "measurement_needs": [
    "Specific surface area (m²/g) of a bone graft powder, including external particle surface and open internal pore surface"
  ],
  "objective_met": false,
  "recommendations": [
    {
      "instrument_id": "EQ10",
      "role": "supplementary",
      "technique": "Environmental scanning electron microscopy (ESEM)",
      "why": "Can qualitatively visualize particle morphology, surface roughness, and visible macroporosity/mesoporosity of the bone graft powder, though it cannot quantify specific surface area in m²/g.",
      "accessories_to_confirm": [
        "Sample stubs and conductive carbon tape",
        "Sputter coater (if high-vacuum imaging of non-conductive bone graft is preferred over low-vacuum ESEM mode)"
      ]
    },
    {
      "instrument_id": "EQ20",
      "role": "supplementary",
      "technique": "Dynamic light scattering (DLS)",
      "why": "Can measure hydrodynamic particle size distribution if the powder is sub-micron to low-micron and can be stably dispersed in a liquid, which gives a rough geometric estimate for smooth spheres but misses internal porosity and fails for rapidly settling coarse granules.",
      "accessories_to_confirm": [
        "Compatible disposable or quartz sizing cuvettes"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "Gas physisorption (BET surface area analysis, typically using N2 or Kr)",
      "why_useful": "Directly measures the total specific surface area in m²/g—including internal pores and surface roughness—by quantifying monolayer gas adsorption on the powder."
    },
    {
      "technique": "Mercury intrusion porosimetry (MIP)",
      "why_useful": "Can estimate specific surface area and pore size distribution for larger mesopores and macropores commonly found in bone graft granules."
    }
  ],
  "clarifying_question": null,
  "summary": "No listed instrument at UMKC can directly measure the specific surface area of a powder in m²/g; this requires a gas physisorption (BET) analyzer, which is not in the current equipment inventory. As supplementary characterization, you can use the environmental scanning electron microscope (EQ10) to inspect particle morphology and surface porosity qualitatively, or the Zetasizer (EQ20) to measure hydrodynamic particle size if the powder is fine enough to remain suspended."
}

{
  "measurement_needs": [
    "Quantitative surface roughness parameters (such as Ra or Sa) and 3D surface topography of polished composite restorations"
  ],
  "objective_met": false,
  "recommendations": [
    {
      "instrument_id": "EQ10",
      "role": "supplementary",
      "technique": "Environmental scanning electron microscopy (ESEM)",
      "why": "Provides high-resolution qualitative images of polishing scratches, filler particle plucking, and surface defects on composite restorations, though it cannot directly output calibrated Ra values without specialized stereo-photogrammetry software.",
      "accessories_to_confirm": [
        "Sample stubs and mounting tape",
        "Low-vacuum/ESEM mode detector for non-conductive dental composites (or sputter coater if operated in high vacuum)"
      ]
    },
    {
      "instrument_id": "EQ08",
      "role": "supplementary",
      "technique": "Confocal laser scanning microscopy (reflection mode z-stacking)",
      "why": "An upright confocal microscope can capture 3D optical sections of opaque surfaces if operated in reflection mode, but as a biological imaging system it lacks calibrated metrological roughness standards and dedicated ISO roughness analysis software.",
      "accessories_to_confirm": [
        "Reflection mode beam splitter/configuration",
        "High-NA dry metallurgical or upright objectives",
        "3D surface topography/roughness analysis software module"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "Contact stylus profilometry",
      "why_useful": "Directly traces the restoration surface with a diamond stylus to provide standardized, calibrated linear roughness values (Ra, Rz) in accordance with ISO 4287."
    },
    {
      "technique": "Optical 3D profilometry (white-light interferometry or materials laser confocal microscopy)",
      "why_useful": "Non-destructively measures calibrated 2D (Ra) and 3D areal (Sa) surface roughness over a defined field of view on polished dental composites."
    },
    {
      "technique": "Atomic force microscopy (AFM)",
      "why_useful": "Provides nanoscale quantitative roughness measurements (Ra/Rq) and 3D topography of highly polished composite surfaces."
    }
  ],
  "clarifying_question": null,
  "summary": "No listed instrument at UMKC is a dedicated metrological profilometer or atomic force microscope capable of directly measuring calibrated Ra surface roughness values. To get quantitative Ra or Sa numbers, you will need a stylus profilometer, a 3D optical profilometer, or an AFM. In the meantime, you can use the environmental scanning electron microscope (EQ10) for qualitative high-resolution visualization of surface scratches and defects, or explore whether the upright confocal microscope (EQ08) can be configured in reflection mode for approximate 3D topography."
}

