  "not_available": [
    {
      "technique": "X-ray micro-computed tomography (micro-CT)",
      "why_useful": "The standard technique for non-destructively imaging the entire 3D volume of an intact extracted tooth at micrometer resolution to quantify internal voids in composite restorations and interfacial gaps along the cavity walls."
    },
    {
      "technique": "Swept-source optical coherence tomography (SS-OCT)",
