      "role": "primary",
      "technique": "Environmental Scanning Electron Microscopy (ESEM)",
      "why": "Directly images nanoparticle surface morphology and size. Operating in low-vacuum (environmental) mode allows you to image non-conductive silica without sputter-coating, though simply sacrificing a tiny microgram aliquot on adhesive carbon tape is usually easiest to keep the rest of your batch pure.",
      "accessories_to_confirm": [
        "Low-vacuum/environmental detector (for uncoated imaging)",
        "SEM sample stubs and conductive adhesive",
        "Sputter coater (if high-vacuum imaging on a sacrificial aliquot is preferred)"
      ]
    },
    {
      "instrument_id": "EQ20",
      "role": "supplementary",
      "technique": "Dynamic Light Scattering (DLS)",
      "why": "Measures the hydrodynamic size distribution and polydispersity of your nanoparticles suspended in liquid, which complements electron microscopy well, though it cannot directly visualize particle shape.",
