}

{
  "measurement_needs": [
    "High-resolution surface imaging to locate contaminants on an implant",
    "Spatially resolved elemental composition analysis (elemental mapping and point analysis) of the surface contaminants"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ10",
      "role": "primary",
      "technique": "Scanning Electron Microscopy with Energy-Dispersive X-ray Spectroscopy (SEM-EDS)",
      "why": "The ESEM can directly image the implant surface at high magnification to pinpoint where contaminants sit and, if equipped with an EDS detector, identify and map the elements present at those exact locations. Note that standard EDS has lower sensitivity to very light elements and probes roughly the top micrometer of the material rather than strictly the outermost atomic layer.",
      "accessories_to_confirm": [
        "Energy-dispersive X-ray spectroscopy (EDS/EDX) detector and elemental mapping software",
        "Backscattered electron (BSE) detector (for atomic-number contrast to quickly spot compositionally distinct contaminants)",
        "Sample holder/stage accommodating the dimensions of the implant"
      ]
    },
    {
      "instrument_id": "EQ14",
      "role": "supplementary",
      "technique": "Stereomicroscopy",
      "why": "Useful for an initial low-magnification visual survey of the whole intact implant to locate larger contaminant regions prior to electron microscopy, though it cannot determine elemental composition.",
      "accessories_to_confirm": [
        "Digital camera for documentation",
        "Appropriate ring light or oblique illumination"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "X-ray Photoelectron Spectroscopy (XPS) or Time-of-Flight Secondary Ion Mass Spectrometry (ToF-SIMS)",
      "why_useful": "If the contaminants are ultrathin films or organic residues restricted to the top few nanometers of the implant surface, XPS or ToF-SIMS would provide true surface-sensitive elemental and chemical-state analysis, whereas SEM-EDS samples deeper into the underlying substrate."
    },
    {
      "technique": "Micro-X-ray Fluorescence (Micro-XRF)",
      "why_useful": "Would allow non-destructive elemental mapping over larger implant areas under ambient conditions with high sensitivity to trace heavy elements."
    }
  ],
  "clarifying_question": null,
  "summary": "To locate surface contaminants on your implant and identify their elemental makeup, the Philips XL30 environmental scanning electron microscope (EQ10) is the best fit, provided you confirm it has an energy-dispersive X-ray spectroscopy (EDS) detector installed for elemental analysis and mapping. You can also use the Nikon SMZ 445 stereomicroscope (EQ14) first for a quick, low-magnification survey to spot contaminated areas. Keep in mind that SEM-EDS probes about a micrometer deep, so if the contamination is an ultrathin nanometer-scale residue, true surface-analysis techniques like XPS (not on the equipment list) would be needed."
}

