{
  "measurement_needs": [
    "Nanoscale particle size distribution (typically 10 to 500 nm for lipid nanoparticles)",
    "Nanoparticle morphology and shape visualization"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ11",
      "role": "primary",
      "technique": "Transmission electron microscopy (TEM)",
      "why": "Optical microscopes cannot resolve lipid nanoparticles because they are smaller than the diffraction limit of visible light. TEM provides the nanometer-scale resolution needed to directly visualize both the size and shape of your nanoparticles, though conventional drying and negative staining under vacuum can flatten or distort soft lipid structures.",
      "accessories_to_confirm": [
        "Digital imaging camera",
        "TEM sample holder",
        "Carbon-coated grids and negative staining reagents (such as uranyl acetate or phosphotungstic acid)",
        "Cryo-holder and plunge-freezing preparation equipment (if cryo-TEM is desired to prevent drying artifacts)"
      ]
    },
    {
      "instrument_id": "EQ20",
      "role": "primary",
      "technique": "Dynamic light scattering (DLS)",
      "why": "DLS rapidly measures the hydrodynamic size distribution and polydispersity of lipid nanoparticles in their native liquid suspension without drying artifacts. However, it calculates size assuming spherical particles and cannot show particle shape.",
      "accessories_to_confirm": [
        "Compatible sizing cuvettes (such as disposable micro-cuvettes or low-volume quartz cells)"
      ]
    },
    {
      "instrument_id": "EQ10",
      "role": "supplementary",
      "technique": "Environmental scanning electron microscopy (ESEM)",
      "why": "ESEM can image surface morphology in a hydrated or low-vacuum state, which helps preserve soft materials, though it generally offers lower resolution than TEM for very small (<100 nm) lipid nanoparticles.",
      "accessories_to_confirm": [
