  "not_available": [
    {
      "technique": "3D optical metrology / structured-light scanning or coordinate measuring machine (CMM)",
      "why_useful": "Would quantify overall part warping and dimensional deviations against the original CAD model across the batch."
    },
    {
      "technique": "X-ray micro-computed tomography (micro-CT)",
